def translate_auth_text(text):
    translated = HELP_KO.get(text) or AUTH_TEXT_KO.get(text)
    if translated is not None:
        return translated
    for pattern, replacement in AUTH_PATTERNS_KO:
        match = re.fullmatch(pattern, text, flags=re.DOTALL)
        if match:
            return match.expand(replacement)
    return text
